function generate(rand, size) {
  const t = Math.floor(rand() * (size === 'small' ? 120 : 1001));
  const count = 1 + Math.floor(rand() * 10), calls = [];
  let time = Math.floor(rand() * 100);
  for (let i = 0; i < count && time <= 1000; i++) {
    calls.push({ t: time, inputs: Array.from({ length: Math.floor(rand() * 4) }, () => Math.floor(rand() * 20) - 5) });
    time += Math.floor(rand() * (size === 'small' ? 150 : 250));
  }
  return [t, calls];
}
